nextflow_process {

    name "Test Process samshee"
    script "../main.nf"
    process "SAMSHEE"
    config "./nextflow.config"
    tag "modules"
    tag "modules_nfcore"
    tag "samshee"

    test("test samplesheet_v1") {

        when {
            params {
                v1_schema             = true
                json_schema_validator = '{"required": ["Data"]}'
                name_schema_validator = null
            }
            process {
                """
                input[0] = [ [ id: 'test', lane:1 ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bcl/miseq_35147139_samplesheet.csv', checkIfExists: true) ]
                input[1] = file("schema.json")
                new File("schema.json").text = '''{
                    "\$schema": "https://json-schema.org/draft/2020-12/schema",
                    "required": ["Settings"]
                }'''
                """
            }
        }

        then {
            assert process.success
            assert snapshot(process.out).match()
        }

    }
    test("test samplesheet_v2") {

        when {
            params {
                v1_schema             = null
                json_schema_validator = null
                name_schema_validator = '{"$ref": "urn:samshee:illuminav2/v1"}'
            }
            process {
                """
                input[0] = [ [ id: 'test', lane:1 ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bcl/nextseq2000_samplesheet.csv', checkIfExists: true) ]
                input[1] = []
                """
            }
        }

        then {
            assert process.success
            assert snapshot(process.out).match()
        }

    }

    test("stub") {

        options "-stub"

        when {
            params {
                v1_schema             = null
                json_schema_validator = null
                name_schema_validator = null
            }
            process {
                """
                input[0] = [ [ id: 'test', lane:1 ], file('samplesheet.csv') ]
                input[1] = []
                """
            }
        }

        then {
            assert process.success
            assert snapshot(process.out).match()
        }

    }

}

process {
    withName: SAMSHEE {
        ext.args = [
            params.json_schema_validator ? "--schema '${params.json_schema_validator}'" : "",
            params.name_schema_validator ? "--schema '${params.name_schema_validator}'" : "",
            params.v1_schema ? "--output-format sectioned" : "",
        ].join(" ").trim()
    }
}
